-- 135 | 2026-11-21 | Hau Giang OLD wave 2/3. Research not a visited/verified storefront.
WITH src AS(SELECT x.*,md5('fbmn:haugiang-old:wave02:'||x.source_key) dg FROM jsonb_to_recordset('[{"district":"Huyện Châu Thành","name":"Nhà sách Minh Thư","address_line":"ĐT925, khu vực huyện Châu Thành cũ (WRF6+M3F)","category":"nha_sach","phone":"02933948644","tax_code":null,"source_key":"gmap:ChIJEwGuv7RhoDER8p_t9-pBiOU","source_url":"https://www.google.com/maps/search/?api=1&query=Nh%C3%A0%20s%C3%A1ch%20Minh%20Th%C6%B0%20%C4%90T925%2C%20khu%20v%E1%BB%B1c%20huy%E1%BB%87n%20Ch%C3%A2u%20Th%C3%A0nh%20c%C5%A9%20(WRF6%2BM3F)%20H%E1%BA%ADu%20Giang&query_place_id=ChIJEwGuv7RhoDER8p_t9-pBiOU","verification_note":"Cần xác minh xã cũ thuộc huyện Châu Thành và tuyến đi."},{"district":"Huyện Phụng Hiệp","name":"Nhà sách Hải Minh","address_line":"ĐT927, xã Hiệp Hưng cũ, huyện Phụng Hiệp (QPHP+M6J)","category":"nha_sach","phone":"02933994667","tax_code":null,"source_key":"gmap:ChIJC4s252H2oDERcvPKLZ5blTo","source_url":"https://www.google.com/maps/search/?api=1&query=Nh%C3%A0%20s%C3%A1ch%20H%E1%BA%A3i%20Minh%20%C4%90T927%2C%20x%C3%A3%20Hi%E1%BB%87p%20H%C6%B0ng%20c%C5%A9%2C%20huy%E1%BB%87n%20Ph%E1%BB%A5ng%20Hi%E1%BB%87p%20(QPHP%2BM6J)%20H%E1%BA%ADu%20Giang&query_place_id=ChIJC4s252H2oDERcvPKLZ5blTo","verification_note":"Nguồn điểm bản đồ, chưa Sales ghé; cần đối chiếu năm 2026."},{"district":"Huyện Vị Thủy","name":"Hiệu sách Thích","address_line":"36 QL61, thị trấn Nàng Mau cũ, huyện Vị Thủy","category":"nha_sach","phone":"0909535595","tax_code":null,"source_key":"gmap:ChIJpYJXaQDvoDERq1MdZIQovtQ","source_url":"https://www.google.com/maps/search/?api=1&query=Hi%E1%BB%87u%20s%C3%A1ch%20Th%C3%ADch%2036%20QL61%2C%20th%E1%BB%8B%20tr%E1%BA%A5n%20N%C3%A0ng%20Mau%20c%C5%A9%2C%20huy%E1%BB%87n%20V%E1%BB%8B%20Th%E1%BB%A7y%20H%E1%BA%ADu%20Giang&query_place_id=ChIJpYJXaQDvoDERq1MdZIQovtQ","verification_note":"Nguồn điểm bản đồ, chưa Sales ghé; cần đối chiếu năm 2026."}]'::jsonb) AS x(
 district text,name text,address_line text,category text,phone text,tax_code text,source_key text,source_url text,verification_note text)),
 ins AS(INSERT INTO public.field_prospects(id,area_visit_id,owner_sub,name,address_line,province,district,category,phone,tax_code,note,status,source_kind,research_source_key,research_source_url,research_batch)
 SELECT (substr(s.dg,1,8)||'-'||substr(s.dg,9,4)||'-5'||substr(s.dg,14,3)||'-8'||substr(s.dg,18,3)||'-'||substr(s.dg,21,12))::uuid,
 NULL,'ef943de4-18f7-49ef-8340-eefb18855534',s.name,s.address_line,'Hậu Giang',s.district,s.category,s.phone,s.tax_code,
 'Nguồn công khai 21/11/2026; CHƯA GHÉ; GPS chưa xác minh; chưa xác minh hoạt động bán lẻ. '||s.verification_note||' Nguồn: '||s.source_url,
 'new','manual',s.source_key,s.source_url,'2026-11-21-hau-giang-old-wave-02'
 FROM src s WHERE s.district IN ('Huyện Châu Thành','Huyện Phụng Hiệp','Huyện Vị Thủy') AND s.source_url LIKE 'https://%'
 AND NOT EXISTS(SELECT 1 FROM customers c WHERE c.province='Hậu Giang' AND c.district=s.district AND (lower(trim(c.name))=lower(trim(s.name)) OR (c.phone IS NOT NULL AND s.phone IS NOT NULL AND c.phone=s.phone)))
 AND NOT EXISTS(SELECT 1 FROM field_prospects p WHERE p.province='Hậu Giang' AND p.district=s.district AND
 (p.research_source_key=s.source_key OR (lower(trim(p.name))=lower(trim(s.name)) AND lower(trim(p.address_line))=lower(trim(s.address_line)))
 OR (p.phone IS NOT NULL AND s.phone IS NOT NULL AND p.phone=s.phone) OR (p.tax_code IS NOT NULL AND s.tax_code IS NOT NULL AND p.tax_code=s.tax_code)))
 ON CONFLICT(research_source_key) WHERE research_source_key IS NOT NULL DO NOTHING RETURNING district,category,phone)
 SELECT district,count(*)::int inserted,count(*) FILTER(WHERE category='nha_sach')::int bookstores FROM ins GROUP BY district ORDER BY district;